{
  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "प्रशान्तशास्त्रार्थविचारचापलं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "निवृत्तनानारसकाव्यकौतुकम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "निरस्तनिःशेषविकल्पविस्तरं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्रपत्तुमन्विच्छति शंकरं मनः ॥ २७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "फलं स्वेच्छालभ्यं प्रतिवनमखेदं क्षितिरुहां",
          "end": "line"
        },
        {
          "n": 2,
          "text": "पयः स्थाने स्थाने शिशिरमधुरं पुण्यसरिताम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मृदुस्पर्शा शय्या सुललितलतापल्लवमयी",
          "end": "line"
        },
        {
          "n": 4,
          "text": "सहन्ते संतापं तदपि धनिनां द्वारि कृपणाः ॥ २८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भव्यं भक्तं ततः किं कदशितमथवा वासरान्ते ततः किं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "कौपीनं वा ततः किं किमथ सितमहच्चाम्बरं वा ततः किम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "एका भार्या ततः किं शतगुणगुणिता कोटिरेका ततः किं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "त्वेको भ्रान्तस्ततः किं करितुरगशतैर्वेष्टितो वा ततः किम् ॥२९॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भिक्षा कामदुघा धेनुः कन्था शीतनिवारिणी ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "अचला तु शिवे भक्तिर्विभवैः किं प्रयोजनम् ॥ ३० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भिक्षाहारमदैन्यमप्रतिहतं भीतिच्छदं सर्वदा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "दुर्मात्सर्यमदाभिमानमथनं दुःखौघविध्वंसनम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "सर्वत्रान्वहमप्रयत्नसुलभं साधुप्रियं पावनं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "शम्भोः सत्रमवार्यमक्षयनिधिं शंसन्ति योगीश्वराः ॥ ३१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
